entries[44502] = { ["name"] = "Bauplan: Feuerstuhl", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung eines Feuerstuhls.\nBenötigt Ingenieurskunst von Nordend (75)\nBenötigt Expedition der Horde\n- Ehrfürchtig\nVerkaufspreis:\nHorde\nFeuerstuhl\nReittier\n(Accountweit)\nBenötigt eine Horde-Rasse\nBenutzen: Lehrt Euch, wie man diesen heißen Ofen fährt.\nBeschwört einen echt heißen Ofen oder parkt ihn.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Wenn sie auch schwer zu bauen und zu pflegen sind, machen diese Feuerstühle den Aufwand durch schiere Großartigkeit wett.\"\nBeruf:\nIngenieurskunst\nAllianz\nChopper des Robogenieurs\nReittier\n(Accountweit)\nBenötigt eine Allianz-Rasse\nBenutzen: Lehrt Euch, wie man diesen Chopper fährt.\nBeschwört einen echt fetten Chopper des Robogenieurs oder parkt ihn.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Dank ausgezeichneter Ingenieurskunst ist dieser Chopper eines der wenigen privaten Fahrzeuge in Azeroth, das zwei Personen befördern kann.\"\nBeruf:\nIngenieurskunstBenötigt Titanstahlbarren (12), Eine Handvoll Kobaltbolzen (40), Arktischer Pelz (2), Geborgene Dunkeleisenteile , Goblinmaschinenkolben (8), Elementiumveredelter Auspuff" }
entries[44503] = { ["name"] = "Bauplan: Chopper des Robogenieurs", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung einer Chopper des Robogenieurs.\nBenötigt Ingenieurskunst von Nordend (75)\nBenötigt Vorhut der Allianz\n- Ehrfürchtig\nVerkaufspreis:\nAllianz\nChopper des Robogenieurs\nReittier\n(Accountweit)\nBenötigt eine Allianz-Rasse\nBenutzen: Lehrt Euch, wie man diesen Chopper fährt.\nBeschwört einen echt fetten Chopper des Robogenieurs oder parkt ihn.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Dank ausgezeichneter Ingenieurskunst ist dieser Chopper eines der wenigen privaten Fahrzeuge in Azeroth, das zwei Personen befördern kann.\"\nBeruf:\nIngenieurskunst\nHorde\nFeuerstuhl\nReittier\n(Accountweit)\nBenötigt eine Horde-Rasse\nBenutzen: Lehrt Euch, wie man diesen heißen Ofen fährt.\nBeschwört einen echt heißen Ofen oder parkt ihn.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Wenn sie auch schwer zu bauen und zu pflegen sind, machen diese Feuerstühle den Aufwand durch schiere Großartigkeit wett.\"\nBeruf:\nIngenieurskunstBenötigt Titanstahlbarren (12), Eine Handvoll Kobaltbolzen (40), Arktischer Pelz (2), Geborgene Dunkeleisenteile , Goblinmaschinenkolben (8), Elementiumveredelter Auspuff" }
entries[44504] = { ["name"] = "Nesingwary 4000", ["text"] = "Wird beim Anlegen gebunden\nDistanz Schusswaffe\n6 - 12 Schaden Geschwindigkeit 3.00\n(3.0 Schaden pro Sekunde)\n+6 Beweglichkeit\nErhöht Eure kritische Trefferwertung um + 5.\n\nPrismatischer Sockel\nSockelbonus: + 1 Angriffskraft\n\nHaltbarkeit 120 / 120\nVerkaufspreis:" }
