entries[44554] = { ["name"] = "Fliegender Teppich", ["text"] = "Reittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört einen fliegenden Teppich oder gibt ihn wieder frei. Dieses Fortbewegungsmittel passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Schneiderei von Nordend (1)\nBenötigt Unerfahrenes Reiten\n\n\"Schwingt Euch auf diesen fliegenden Teppich, um Azeroth schwebend, taumelnd und wiegend zu erkunden.\"\nBeruf:\nSchneiderei" }
entries[44555] = { ["name"] = "Schneller Mondgespinstteppich", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\n80 ( 80)\nBenötigt Schneiderei von Nordend (75)\n\"Lehrt Euch, wie man diesen Teppich beschwört. Das ist ein Flugreittier.\"" }
