entries[44689] = { ["name"] = "Gepanzerter weißer Greif", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenötigt eine Allianz-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört einen reitbaren gepanzerten weißen Greifen oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Das Nette ist, wenn sie angreifen, verfärbt das Blut fast nie ihre Federn. - Mei Francis\"\nVerkäufer:\nMei Francis\nZone:\nKristallsangwald\nKosten:" }
entries[44690] = { ["name"] = "Gepanzerter blauer Windreiter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenötigt eine Horde-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört einen reitbaren gepanzerten blauen Windreiter oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Sie stammen nicht aus Nordend, haben sich aber außerordentlich gut an die Kälte angepasst. - Mei Francis\"\nVerkäufer:\nMei Francis\nZone:\nKristallsangwald\nKosten:" }
