entries[44791] = { ["name"] = "Nobelgartenschokolade", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Stellt im Verlauf von 24 Sek. ( 656250 / 5 * 24) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 15 Min. lang Ausdauer und Vielseitigkeit.\nBenötigt Nobelgartenfest" }
entries[44792] = { ["name"] = "Blühender Zweig", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Verkleidet das anvisierte Gruppenmitglied als Hase.\n5 Aufladungen" }
entries[44793] = { ["name"] = "Foliant der Verwandlung: Hase", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Magier\nBenutzen: Lehrt Verwandlung: Hase.\nVerwandelt den Gegner in einen harmlosen Hasen, der 1 Min. lang handlungsunfähig umherirrt. In diesem Zustand kann das Opfer nicht agieren, regeneriert aber seine Gesundheit sehr schnell. Schaden beendet den Effekt. Es kann nur jeweils 1 Ziel betroffen sein.\n\nWirkt nur bei Tieren, Humanoiden und Kleintieren. [ Glyphe 'Kleintierverwandlung' : Bei Kleintieren kann der Zauber mehrere Ziele verwandeln, und die Verwandlung hält 1 Tag lang an ]" }
entries[44794] = { ["name"] = "Frühlingshasenpfote", ["text"] = "Benutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Euren Frühlingshasen beschwören oder wieder freigeben.\n80 ( 80)" }
