entries[44802] = { ["name"] = "Geliehener Eierkorb", ["text"] = "QuestgegenstandIn Schildhand geführt\nBenutzen: Erhöht die Geschwindigkeit 10 Sek. lang um 60%. Funktioniert nur, wo während des Nobelgartenfestes bunt gefärbte Eier versteckt sind. (10 Sek. Abklingzeit)\nBenötigt Nobelgartenfest" }
entries[44803] = { ["name"] = "Frühlingsreif", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nKopf Kosmetisch\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
