entries[44808] = { ["name"] = "Magieerfüllte Rüstung der Horde", ["text"] = "Questgegenstand\n\"Die Essenz des Soldaten haftet an der Rüstung.\"" }
entries[44809] = { ["name"] = "Kräuterbeutel der Horde", ["text"] = "Questgegenstand\n\"Duftend und zerbrechlich\"" }
entries[44810] = { ["name"] = "Truthahnkäfig", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Euren fetten Truthahn beschwören oder wieder freigeben.\n80 ( 80)" }
entries[44811] = { ["name"] = "Foliant der Verwandlung: Truthahn", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Magier\nBenutzen: Lehrt 'Verwandlung: Truthahn'.\nVerwandelt den Gegner in einen Truthahn, der 1 Min. lang handlungsunfähig umherirrt. In diesem Zustand kann das Opfer nicht agieren, regeneriert aber seine Gesundheit sehr schnell. Schaden beendet den Effekt. Es kann nur jeweils 1 Ziel betroffen sein.\n\nWirkt nur bei Tieren, Humanoiden und Kleintieren. [ Glyphe 'Kleintierverwandlung' : Bei Kleintieren kann der Zauber mehrere Ziele verwandeln, und die Verwandlung hält 1 Tag lang an ]\nVerkaufspreis:" }
entries[44812] = { ["name"] = "Truthahnbüchse", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Bedeckt das Ziel mit Truthahnfedern.\nBenötigt Pilgerfreudenfest" }
entries[44815] = { ["name"] = "Armschiene - Großer Sturmangriff", ["text"] = "Benutzen: Armschienen dauerhaft verzaubern, sodass die Angriffskraft um 6 erhöht wird. Kann nicht auf Gegenstände über Stufe 376 angewandt werden.\nVerkaufspreis:" }
entries[44817] = { ["name"] = "Der Unruhestifter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verwandelt ein befreundetes Ziel in ein Schaf und zwingt es, 15 Sek. lang so herumzuwandern. Während das Schaf herumwandert, kann es weder angreifen noch Zauber wirken, regeneriert sich aber sehr schnell. Jeglicher erlittene Schaden verwandelt das Ziel in seine normale Gestalt zurück. Es kann immer nur jeweils ein Ziel verwandelt werden. Wirkt nur bei Wildtieren, Humanoiden und Tieren und ausschließlich in Dalaran.\nVerkaufspreis:" }
entries[44818] = { ["name"] = "Nobelgartenei", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nBenutzen: Platziert ein bunt gefärbtes Ei, das Nobelgartengeschenke enthält. (1 Stunde Abklingzeit)\nBenötigt Nobelgartenfest" }
