entries[44858] = { ["name"] = "Rezept: Moosbeerenchutney", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man Moosbeerenchutney zubereitet.\nBenötigt Klassische Kochkunst (160)\n\nMoosbeerenchutney\nBenutzen: Stellt im Verlauf von 20 Sek. Eure Gesundheit und Euer Mana vollständig wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang Vielseitigkeit.\nBenötigt Pilgerfreudenfest\nVerkaufspreis:\nBenötigt Säuerliche Sumpfmoosbeeren , Honig" }
entries[44859] = { ["name"] = "Rezept: Kandierte Süßkartoffel", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man kandierte Süßkartoffeln zubereitet.\nBenötigt Klassische Kochkunst (220)\n\nKandierte Süßkartoffel\nBenutzen: Stellt im Verlauf von 20 Sek. Eure Gesundheit und Mana vollständig wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang Tempo.\nBenötigt Pilgerfreudenfest\nVerkaufspreis:\nBenötigt Süßkartoffel von Teldrassil , Honig , Herbstliche Gewürze" }
entries[44860] = { ["name"] = "Rezept: Gewürzbrotfüllung", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man Gewürzbrotfüllung zubereitet.\nBenötigt Klassische Kochkunst (1)\n\nGewürzbrotfüllung\nBenutzen: Stellt im Verlauf von 20 Sek. Eure Gesundheit und Euer Mana vollständig wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang Ausdauer.\nBenötigt Pilgerfreudenfest\nVerkaufspreis:\nBenötigt Gewürzbrot , Herbstliche Gewürze" }
entries[44861] = { ["name"] = "Rezept: Langsam gerösteter Truthahn", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man langsam gerösteten Truthahn zubereitet.\nBenötigt Klassische Kochkunst (280)\n\nLangsam gerösteter Truthahn\nBenutzen: Stellt im Verlauf von 20 Sek. Eure Gesundheit und Euer Mana vollständig wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang Meisterschaft.\nBenötigt Pilgerfreudenfest\nVerkaufspreis:\nBenötigt Wilder Truthahn , Honig (2), Herbstliche Gewürze" }
entries[44862] = { ["name"] = "Rezept: Kürbiskuchen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man Kürbiskuchen zubereitet.\nBenötigt Klassische Kochkunst (100)\n\nKürbiskuchen\nBenutzen: Stellt im Verlauf von 20 Sek. Eure Gesundheit und Euer Mana vollständig wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang kritischen Trefferwert.\nBenötigt Pilgerfreudenfest\nVerkaufspreis:\nBenötigt Reifer Elwynnkürbis , Honig" }
