entries[44888] = { ["name"] = "Bärenklaubündel", ["text"] = "Questgegenstand\nBenutzen: Kombiniert den Bärenklau mit Flinkfuß' Schwanzfedern vor der uralten Bärenstatue in der Nähe des Hains der Uralten." }
entries[44889] = { ["name"] = "Gesegnetes Kräuterbündel", ["text"] = "Questgegenstand\nBenutzen: Läutert einen Furbolg der Schwarzfellfeste von Verderbnis. Macht der Verderbnis so schnell wie möglich ein Ende, denn so befreit Ihr den Furbolg und er wird nicht länger aggressiv sein. (5 Sek. Abklingzeit)" }
entries[44890] = { ["name"] = "To'kinis Blasrohr", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Schießt auf den ausgewählten Frostleoparden oder Eispfotenbären, um diesen ruhig zu stellen und in einen leichten Schlaf zu versetzen. Kann nicht im Kampf eingesetzt werden oder wenn sich die Frostleoparden oder Eispfotenbären im Kampf befinden. (5 Sek. Abklingzeit)" }
